#include <iostream>
#include <string>
#include <algorithm>

int main() {
    std::string s;
    int n;
    std::cin >> n;
    while (n--) {
        std::cin >> s;
        for (char c = 'a'; c <= 'h'; ++c) {
            if (c != s[0]) {
                std::cout << c << s[1] << std::endl;
            }
        }
        for (char c = '1'; c <= '8'; ++c) {
            if (c != s[1]) {
                std::cout << s[0] << c << std::endl;
            }
        }
        std::cout << std::endl;
    }
    return 0;
}
